function json(data, status = 200, extraHeaders = {}) {
  return Response.json(data, {
    status,
    headers: { "Cache-Control": "no-store", ...extraHeaders }
  });
}

function getCookie(request, name) {
  const raw = request.headers.get("Cookie") || "";
  const m = raw.match(new RegExp("(?:^|;\\s*)" + name.replace(/[.*+?^${}()|[\\]\\\\]/g, "\\$&") + "=([^;]*)"));
  return m ? decodeURIComponent(m[1]) : "";
}

function authorized(request, env) {
  const h = request.headers.get("Authorization") || "";
  const bearer = h.startsWith("Bearer ") ? h.slice(7) : "";
  const cookie = getCookie(request, "thinkshop_admin");
  return !!env.ADMIN_TOKEN && (bearer === env.ADMIN_TOKEN || cookie === env.ADMIN_TOKEN);
}

const DEFAULT_PRODUCTS = [{"id":1,"name":"کاتان","price":2950000,"rating":"۴.۸","reviews":"۹۶","type":"منتخب","image":"data:image/webp;base64,","desc":"یک بازی استراتژیک و جذاب برای ساخت‌وساز، تجارت و رقابت خانوادگی."},{"id":2,"name":"کد نیمز","price":1690000,"rating":"۴.۷","reviews":"۷۸","type":"منتخب","image":"data:image/webp;base64,","desc":"یک بازی کلمه‌ای گروهی و هیجان‌انگیز برای جمع‌های دوستانه."},{"id":3,"name":"دیکسیت","price":2400000,"rating":"۴.۶","reviews":"۶۶","type":"منتخب","image":"data:image/webp;base64,","desc":"بازی خلاقانه‌ای بر پایه تصویر، داستان‌پردازی و حدس زدن ذهن دوستان."},{"id":4,"name":"وینگزپن","price":2850000,"rating":"۴.۹","reviews":"۸۲","type":"منتخب","image":"data:image/webp;base64,","desc":"یک بازی استراتژیک زیبا با موضوع پرندگان و ساخت زیستگاه."},{"id":5,"name":"جنگل شب","price":1250000,"rating":"۴.۵","reviews":"۴۸","type":"پرفروش","image":"data:image/webp;base64,","desc":"یک ماجراجویی فکری با فضای جنگلی و تصمیم‌های غافلگیرکننده."},{"id":6,"name":"پازل‌برتر","price":980000,"rating":"۴.۶","reviews":"۵۴","type":"پرفروش","image":"data:image/webp;base64,","desc":"مجموعه‌ای از چالش‌های ذهنی برای تقویت تمرکز و حل مسئله."},{"id":7,"name":"آوالون","price":1150000,"rating":"۴.۶","reviews":"۷۱","type":"پرفروش","image":"data:image/webp;base64,","desc":"بازی نقش مخفی و استدلالی برای جمع‌های دوستانه و پرهیجان."},{"id":8,"name":"کواترو","price":1480000,"rating":"۴.۷","reviews":"۵۹","type":"پرفروش","image":"data:image/webp;base64,","desc":"بازی سریع و رقابتی برای کسانی که از تصمیم‌گیری‌های کوتاه و هیجان‌انگیز لذت می‌برند."}];

async function seedDefaults(env) {
  const row = await env.DB.prepare(`SELECT COUNT(*) AS c FROM products`).first();
  if (Number(row?.c || 0) > 0) return;
  for (const p of DEFAULT_PRODUCTS) {
    await env.DB.prepare(
      `INSERT OR IGNORE INTO products (id,name,price,image,desc,type,featured,best,rating,reviews,cover)
       VALUES (?,?,?,?,?,?,?,?,?,?,?)`
    ).bind(
      Number(p.id), String(p.name || ""), Number(p.price || 0), String(p.image || ""),
      String(p.desc || ""), String(p.type || "فروشگاه"), p.featured ? 1 : 0,
      p.best ? 1 : 0, String(p.rating || "۵.۰"), String(p.reviews || "۰"), String(p.cover || "ThinkShop")
    ).run();
  }
}

async function productsApi(request, env) {
  if (!env.DB) return json({ ok: false, error: "D1 binding DB پیدا نشد." }, 500);

  if (request.method === "GET") {
    await seedDefaults(env);
    const { results } = await env.DB.prepare(
      `SELECT id,name,price,image,desc,type,featured,best,rating,reviews,cover,created_at,updated_at
       FROM products ORDER BY id ASC`
    ).all();
    return json({ ok: true, products: results.map(p => ({ ...p, featured: !!p.featured, best: !!p.best })) });
  }

  if (!authorized(request, env)) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);

  if (request.method === "POST") {
    const p = await request.json();
    const name = String(p.name || "").trim();
    const price = Number(p.price);
    if (!name || !Number.isFinite(price) || price < 0) return json({ ok: false, error: "نام و قیمت معتبر الزامی است." }, 400);
    const id = Number(p.id || Date.now());
    await env.DB.prepare(
      `INSERT INTO products (id,name,price,image,desc,type,featured,best,rating,reviews,cover)
       VALUES (?,?,?,?,?,?,?,?,?,?,?)`
    ).bind(id,name,Math.round(price),String(p.image || ""),String(p.desc || ""),String(p.type || "فروشگاه"),p.featured ? 1 : 0,p.best ? 1 : 0,String(p.rating || "۵.۰"),String(p.reviews || "۰"),String(p.cover || "ThinkShop")).run();
    return json({ ok: true, id });
  }

  if (request.method === "PUT") {
    const p = await request.json();
    const id = Number(p.id);
    const name = String(p.name || "").trim();
    const price = Number(p.price);
    if (!id || !name || !Number.isFinite(price) || price < 0) return json({ ok: false, error: "اطلاعات محصول نامعتبر است." }, 400);
    const result = await env.DB.prepare(
      `UPDATE products SET name=?,price=?,image=?,desc=?,type=?,featured=?,best=?,rating=?,reviews=?,cover=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`
    ).bind(name,Math.round(price),String(p.image || ""),String(p.desc || ""),String(p.type || "فروشگاه"),p.featured ? 1 : 0,p.best ? 1 : 0,String(p.rating || "۵.۰"),String(p.reviews || "۰"),String(p.cover || "ThinkShop"),id).run();
    if (!result.meta?.changes) return json({ ok: false, error: "محصول پیدا نشد." }, 404);
    return json({ ok: true });
  }

  if (request.method === "DELETE") {
    const id = Number(new URL(request.url).searchParams.get("id"));
    if (!id) return json({ ok: false, error: "شناسه محصول نامعتبر است." }, 400);
    const result = await env.DB.prepare(`DELETE FROM products WHERE id=?`).bind(id).run();
    if (!result.meta?.changes) return json({ ok: false, error: "محصول پیدا نشد." }, 404);
    return json({ ok: true });
  }

  return json({ ok: false, error: "Method Not Allowed" }, 405);
}

async function loginApi(request, env) {
  if (request.method !== "POST") return json({ ok: false, error: "Method Not Allowed" }, 405);
  const body = await request.json().catch(() => ({}));
  const password = String(body.password || "");
  if (!env.ADMIN_PASSWORD || password !== env.ADMIN_PASSWORD) return json({ ok: false, error: "رمز مدیریت اشتباه است." }, 401);
  if (!env.ADMIN_TOKEN) return json({ ok: false, error: "ADMIN_TOKEN در Cloudflare تنظیم نشده است." }, 500);
  return json({ ok: true }, 200, {
    "Set-Cookie": `thinkshop_admin=${encodeURIComponent(env.ADMIN_TOKEN)}; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=86400`
  });
}

async function logoutApi(request, env) {
  return json({ ok: true }, 200, {
    "Set-Cookie": "thinkshop_admin=; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=0"
  });
}

async function meApi(request, env) {
  return json({ ok: authorized(request, env) }, authorized(request, env) ? 200 : 401);
}

async function settingsApi(request, env) {
  if (!env.DB) return json({ ok: false, error: "D1 binding DB پیدا نشد." }, 500);
  if (!authorized(request, env)) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
  if (request.method === "GET") {
    const row = await env.DB.prepare(`SELECT value FROM settings WHERE key='gateway'`).first();
    let gateway = {}; try { gateway = JSON.parse(row?.value || "{}"); } catch {}
    return json({ ok: true, gateway });
  }
  if (request.method === "PUT") {
    const body = await request.json();
    const gateway = { gatewayName:String(body.gatewayName||""), gatewayUrl:String(body.gatewayUrl||""), merchantId:String(body.merchantId||""), enabled:!!body.enabled };
    await env.DB.prepare(`INSERT INTO settings(key,value) VALUES('gateway',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value`).bind(JSON.stringify(gateway)).run();
    return json({ ok:true, gateway });
  }
  return json({ ok:false,error:"Method Not Allowed" },405);
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    try {
      if (url.pathname === "/api/products") return await productsApi(request, env);
      if (url.pathname === "/api/admin/login") return await loginApi(request, env);
      if (url.pathname === "/api/admin/logout") return await logoutApi(request, env);
      if (url.pathname === "/api/admin/me") return await meApi(request, env);
      if (url.pathname === "/api/admin/settings") return await settingsApi(request, env);
      if (env.ASSETS) return env.ASSETS.fetch(request);
      return new Response("Thinkshop assets binding ASSETS پیدا نشد.", { status: 500 });
    } catch (e) {
      return json({ ok:false, error:e?.message || "خطای سرور" },500);
    }
  }
};
